from collections import defaultdict, deque

def findOrder(dict, N, K):
    graph = defaultdict(list)
    in_degree = {char: 0 for char in range(K)}

    # Create graph and in-degree count
    for i in range(N - 1):
        word1, word2 = dict[i], dict[i + 1]
        for j in range(min(len(word1), len(word2))):
            if word1[j] != word2[j]:
                graph[word1[j]].append(word2[j])
                in_degree[ord(word2[j]) - ord('a')] += 1
                break

    # Topological sort using Kahn's algorithm
    queue = deque([char for char in in_degree if in_degree[char] == 0])
    result = []

    while queue:
        node = queue.popleft()
        result.append(chr(ord('a') + node))
        for neighbor in graph[chr(ord('a') + node)]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return ''.join(result)

# Example usage:
# N = 5, K = 4
